// swift-tools-version: 5.9
// The swift-tools-version declares the minimum version of Swift required to build this package.

import PackageDescription

let package = Package(
    name: "fontations",
    platforms: [
        .iOS("13.0")
    ],
    products: [
        .library(name: "fontations", targets: ["fontations"])
    ],
    dependencies: [
        // Generated by the Flutter tool, vends Flutter.framework to plugins.
        .package(name: "FlutterFramework", path: "../FlutterFramework")
    ],
    targets: [
        // Prebuilt Rust library. CocoaPods compiles Rust from source through a
        // cargokit script phase; SwiftPM has no script phases and its build
        // tool plugins run sandboxed, so cargo cannot run during the Xcode
        // build and the artifact is built ahead of time instead:
        // ./scripts/build_xcframework.sh
        .binaryTarget(name: "fontations_rust", path: "fontations.xcframework"),
        .target(
            name: "fontations",
            dependencies: [
                "fontations_rust",
                .product(name: "FlutterFramework", package: "FlutterFramework"),
            ]
        )
    ]
)
